import subprocess, re, pathlib
branch=set()
for name in ['rachel','monica','phoebe','joey','chandler','ross']:
    raw=subprocess.check_output(['git','log','--format=%H%x1f%B%x1e', f'origin/friend/{name}'], text=True)
