        if not rec.strip(): continue
        parts=rec.split('\x1f',1)
        sha=parts[0]; body=parts[1]
        if re.search(r'^Friend-Message:\s*1\s*$', body, re.M):
            branch.add(sha)
main={}
for p in pathlib.Path('.').glob('S*/*.md'):
    txt=p.read_text()
    for m in re.finditer(r'^Source: friend/(\w+) @ ([0-9a-f]{40})$', txt, re.M):
        main[m.group(2)] = (m.group(1), str(p))
for s,(name,p) in main.items():
    if s not in branch:
        print(s, name, p)
